  1→//! Shared display helpers for step status formatting.
  2→//!
  3→//! These helpers are used by `status`, `last`, and any other command that
  4→//! needs to render [`StepStatus`] values consistently.
  5→
  6→use crate::state::StepStatus;
  7→use crate::ui::{StatusKind, UserInterface};
  8→
  9→/// Return a StatusKind for a step status.
 10→pub fn status_kind(status: &StepStatus) -> StatusKind {
 11→    StatusKind::from(*status)
 12→}
 13→
 14→/// Return the icon string for a step status (TTY output).
 15→pub fn status_icon(status: &StepStatus) -> &'static str {
 16→    status_kind(status).icon()
 17→}
 18→
 19→/// Return a bracketed symbol for a step status (non-TTY output).
 20→pub fn status_symbol(status: &StepStatus) -> &'static str {
 21→    status_kind(status).bracketed()
 22→}
 23→
 24→/// Print a single step's status line, styled by severity.
 25→pub fn show_step_status(ui: &mut dyn UserInterface, name: &str, status: &StepStatus) {
 26→    let kind = status_kind(status);
 27→    let line = format!("  {} {}", kind.icon(), name);
 28→    match status {
 29→        StepStatus::Success => ui.success(&line),
 30→        StepStatus::Failed => ui.error(&line),
 31→        StepStatus::Skipped => ui.warning(&line),
 32→        StepStatus::NeverRun => ui.message(&line),
 33→    }
 34→}
 35→
 36→#[cfg(test)]
 37→mod tests {
 38→    use super::*;
 39→
 40→    #[test]
 41→    fn status_symbol_values() {
 42→        assert_eq!(status_symbol(&StepStatus::Success), "[ok]");
 43→        assert_eq!(status_symbol(&StepStatus::Failed), "[FAIL]");
 44→        assert_eq!(status_symbol(&StepStatus::Skipped), "[skip]");
 45→        assert_eq!(status_symbol(&StepStatus::NeverRun), "[pending]");
 46→    }
 47→
 48→    #[test]
 49→    fn status_icon_values() {
 50→        assert_eq!(status_icon(&StepStatus::Success), "✓");
 51→        assert_eq!(status_icon(&StepStatus::Failed), "✗");
 52→        assert_eq!(status_icon(&StepStatus::Skipped), "○");
 53→        assert_eq!(status_icon(&StepStatus::NeverRun), "◌");
 54→    }
 55→
 56→    #[test]
 57→    fn status_kind_conversion() {
 58→        assert_eq!(status_kind(&StepStatus::Success), StatusKind::Success);
 59→        assert_eq!(status_kind(&StepStatus::Failed), StatusKind::Failed);
 60→        assert_eq!(status_kind(&StepStatus::Skipped), StatusKind::Skipped);
 61→        assert_eq!(status_kind(&StepStatus::NeverRun), StatusKind::Pending);
 62→    }
 63→
 64→    #[test]
 65→    fn show_step_status_uses_correct_ui_method() {
 66→        use crate::ui::MockUI;
 67→
 68→        let mut ui = MockUI::new();
 69→        show_step_status(&mut ui, "step1", &StepStatus::Success);
 70→        assert!(ui.successes().iter().any(|m| m.contains("step1")));
 71→
 72→        show_step_status(&mut ui, "step2", &StepStatus::Failed);
 73→        assert!(ui.errors().iter().any(|m| m.contains("step2")));
 74→
 75→        show_step_status(&mut ui, "step3", &StepStatus::Skipped);
 76→        assert!(ui.warnings().iter().any(|m| m.contains("step3")));
 77→
 78→        show_step_status(&mut ui, "step4", &StepStatus::NeverRun);
 79→        assert!(ui.messages().iter().any(|m| m.contains("step4")));
 80→    }
 81→
 82→    #[test]
 83→    fn show_step_status_includes_icons() {
 84→        use crate::ui::MockUI;
 85→
 86→        let mut ui = MockUI::new();
 87→        show_step_status(&mut ui, "step1", &StepStatus::Success);
 88→        assert!(ui.successes().iter().any(|m| m.contains("✓")));
 89→
 90→        show_step_status(&mut ui, "step2", &StepStatus::Failed);
 91→        assert!(ui.errors().iter().any(|m| m.contains("✗")));
 92→
 93→        show_step_status(&mut ui, "step3", &StepStatus::Skipped);
 94→        assert!(ui.warnings().iter().any(|m| m.contains("○")));
 95→
 96→        show_step_status(&mut ui, "step4", &StepStatus::NeverRun);
 97→        assert!(ui.messages().iter().any(|m| m.contains("◌")));
 98→    }
 99→}
